//! display/dc/dio/dcn20/dcn20_stream_encoder.{h,c} + inc/hw/stream_encoder.h
//! (Linux 6.18.55), with the `stream_enc_regs`/`se_shift`/`se_mask` table of
//! dcn21_resource.c: the DIG stream encoders (DP/HDMI output framing). Renoir
//! has `res_cap_rn.num_stream_encoder` (5), on DIGA..DIGE.
//!
//! `dcn21_stream_encoder_create` → `dcn20_stream_encoder_construct` stores the
//! engine id, funcs identity and register pointers; it writes no register. The
//! register table is machine-generated by `dcgen.py` from `SE_DCN2_REG_LIST` /
//! `SE_COMMON_MASK_SH_LIST_DCN20` (73 regs x 5, 187 shift/mask fields).
//!
//! This block is a dormant leaf: the pool populates `stream_enc[]` from inside
//! `resource_construct` (the stream/link-encoder/audio assembly), which joins
//! as its own unit — this file is the encoder it will create.
#![allow(dead_code)]

use crate::dc_types::engine_id;
use crate::regs::*;
use alloc::boxed::Box;

/// Which `stream_encoder_funcs` vtable the base points at (dcn20_stream_encoder.c).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum stream_encoder_funcs {
    dcn20_str_enc_funcs,
}

/// `struct stream_encoder` (inc/hw/stream_encoder.h): the encoder base. Ported
/// grow-as-reached — the construct stores funcs, id and stream_enc_inst; `ctx`
/// and `bp` (the dc_bios pointer) are not stored (as with `clock_source`), and
/// `vpg`/`afmt`/`apg` are DCN3+ sub-blocks.
#[derive(Default)]
pub struct stream_encoder {
    pub funcs: Option<stream_encoder_funcs>,
    pub id: engine_id,
    pub stream_enc_inst: u32,
}

/// `struct dcn10_stream_encoder` (dcn10_stream_encoder.h): the concrete encoder
/// (the dcn20 construct reuses the dcn10 object).
#[derive(Default)]
pub struct dcn10_stream_encoder {
    pub base: stream_encoder,
    pub regs: Option<&'static dcn10_stream_enc_registers>,
    pub se_shift: Option<&'static dcn10_stream_encoder_shift>,
    pub se_mask: Option<&'static dcn10_stream_encoder_mask>,
}

/// `dcn20_stream_encoder_construct` (dcn20_stream_encoder.c): store the engine
/// id, funcs and registers. `stream_enc_inst = eng_id - ENGINE_ID_DIGA`.
pub fn dcn20_stream_encoder_construct(
    enc1: &mut dcn10_stream_encoder,
    eng_id: engine_id,
    regs: &'static dcn10_stream_enc_registers,
    se_shift: &'static dcn10_stream_encoder_shift,
    se_mask: &'static dcn10_stream_encoder_mask,
) {
    enc1.base.funcs = Some(stream_encoder_funcs::dcn20_str_enc_funcs);
    enc1.base.id = eng_id;
    enc1.regs = Some(regs);
    enc1.se_shift = Some(se_shift);
    enc1.se_mask = Some(se_mask);
    enc1.base.stream_enc_inst = (eng_id as i32 - engine_id::ENGINE_ID_DIGA as i32) as u32;
}

/// `dcn21_stream_encoder_create` (dcn21_resource.c): allocate and construct the
/// encoder for `eng_id` (DIGA..DIGE index into `SE_REGS`).
pub fn dcn21_stream_encoder_create(eng_id: engine_id) -> Box<dcn10_stream_encoder> {
    let mut enc1 = Box::new(dcn10_stream_encoder::default());
    let i = (eng_id as i32 - engine_id::ENGINE_ID_DIGA as i32) as usize;
    dcn20_stream_encoder_construct(&mut enc1, eng_id, &SE_REGS[i], &SE_SHIFT, &SE_MASK);
    enc1
}

